"""Historical tool-input literal recovery, NOT a new translation.

The following AR/RU strings are copied from the root's preserved continue.py
and finish308.py tool-call payloads. Assembly/paths are adapted only to isolate
recovery; the three finish308 wording patches and final verified305 correction
are applied explicitly below. This does not recreate original Git commit IDs.
"""
import json,hashlib
from pathlib import Path
P=Path('/workspace/recovery/root303')
rows=[json.loads(l) for l in (P/'base/source-pages.jsonl').read_text().splitlines()]
t=json.loads((P/'base/translation.json').read_text())
base_count=len(t['paragraphs'])
def sha(s):return hashlib.sha256(s.encode()).hexdigest()
def source(page,i,ar,complete=True):
 r=next((r for r in rows if r['printed_page']==page),None)
 if r is None:
  r={'printed_page':page,'pdf_leaf':page,'witness_status':'control_print_visually_read','publisher_footnote_text_imported':False,'paragraphs':[]}; rows.append(r)
 id=f'v4-p{page:03d}-{i:02d}'
 q={'id':id,'ar':ar,'sha256':sha(ar),'witness':'uploaded_2019_control_pdf','source_complete':complete}
 old=next((q for q in r['paragraphs'] if q['id']==id),None)
 if old:old.update(q)
 else:r['paragraphs'].append(q)
 return id
new=[]
def unit(ids,ru):
 ar=' '.join(next(q['ar'] for r in rows for q in r['paragraphs'] if q['id']==id) for id in ids)
 u={'id':ids[0]+'-ru','source_ids':ids,'printed_pages':sorted({int(id[4:7]) for id in ids}),'ar':ar,'ru':ru,'draft_status':'draft','print_collation':'control_image_read','independent_human_review':False}
 t['paragraphs'].append(u);new.append(u['id'])
def pair(p,i,ar,ru):unit([source(p,i,ar)],ru)
pair(303,3,'فسبحان من حال بين المعطلة وبين محبته ومعرفته، والسرور والفرح به، والشوق إلى لقائه، وانتظار لذة النظر إلى وجهه، والتمتع بخطابه في محل كرامته ودار ثوابه! ولو رآها أهلا لذلك لمن عليها به، وأكرمها به، إذ ذلك أعظم كرامة يكرم بها عبده، والله أعلم حيث يجعل كرامته ويضع نعمته، {وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من الله عليهم من بيننا أليس الله بأعلم بالشاكرين} [الأنعام: 53]، {وإذا جاءتهم آية قالوا لن نؤمن حتى نؤتى مثل ما أوتي رسل الله الله أعلم حيث يجعل رسالته} [الأنعام: 124]، {أهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون} [الزخرف: 32].','Пречист Тот, Кто преградил отрицающим Его качества путь к любви к Нему и познанию Его, к отраде и радости о Нём, к стремлению встретиться с Ним и ожиданию наслаждения от взирания на Его Лик, к наслаждению Его речью в обители Его почёта и воздаяния! Если бы Он счёл эти души достойными такого дара, то непременно облагодетельствовал бы их и почтил им. Ведь это величайший почёт, которого Он удостаивает Своего раба. Аллах лучше знает, кого удостоить Своего почёта и кому даровать Свою милость. {وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من الله عليهم من بيننا أليس الله بأعلم بالشاكرين} — «Так Мы испытали одних из них другими, чтобы они сказали: „Неужели именно этих среди нас Аллах облагодетельствовал?“ Разве Аллах не лучше знает благодарных?» (6:53). {وإذا جاءتهم آية قالوا لن نؤمن حتى نؤتى مثل ما أوتي رسل الله الله أعلم حيث يجعل رسالته} — «Когда к ним приходит знамение, они говорят: „Мы не уверуем, пока нам не будет даровано то же, что было даровано посланникам Аллаха“. Аллах лучше знает, кому вверить Своё послание» (6:124). {أهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون} — «Разве они распределяют милость твоего Господа? Мы распределили между ними средства к жизни в этом мире и возвысили одних над другими по степеням, чтобы одни брали других себе на службу. Милость твоего Господа лучше того, что они собирают» (43:32).')
a=source(303,4,'وليس جحودهم صفاته سبحانه وحقائق أسمائه ـ في الحقيقة ـ تنزيها، وإنما هو حجاب ضرب عليهم، فظنوه تنزيها، كما ضرب حجاب الشرك والبدع المضلة والشهوات المردية على قلوب أصحابها، وزين لهم سوء')
b=source(304,1,'أعمالهم فرأوها حسنة.')
unit([a,b],'Их отрицание Его качеств, Пречист Он, и подлинного содержания Его имён в действительности вовсе не является очищением представления о Нём от недостатков. Это лишь завеса, наброшенная на них, которую они сочли таким очищением. Подобным образом сердца других людей закрыты завесой многобожия, вводящих в заблуждение нововведений и губительных страстей: дурные дела были приукрашены для них, и они увидели их прекрасными.')
pair(304,2,'عدنا إلى شرح كلامه:','Вернёмся к разъяснению его слов.')
pair(304,3,'قوله: (قد وردت أساميها بالرسالة... ) إلى آخره.','Его слова: «Их наименования переданы через послание…» — и далее.')
pair(304,4,'ذكر أن إثبات الصفات دل عليه: الوحي الذي جاء من الله على لسان رسوله، والحس الذي شاهد به البصير آثار الصنعة فاستدل بها على صفات صانعها، والعقل الذي طابت حياته بزرع الفكر، والقلب الذي حيي بحسن النظر بين التعظيم والاعتبار.','Он упомянул, что об утверждении качеств свидетельствуют: откровение, пришедшее от Аллаха устами Его посланника; чувственное восприятие, посредством которого зрячий увидел следы творения и заключил по ним о качествах Творца; разум, чья жизнь стала благой благодаря посеву размышления; и сердце, ожившее от верного созерцания, соединяющего возвеличивание с извлечением урока.')
a=source(304,5,'فأما الرسالة، فإنها جاءت بإثبات الصفات إثباتا مفصلا على وجه أزال الشبهة وكشف الغطاء وحصل العلم اليقين، ورفع الشك والريب، فانجلت له الصدور واطمأنت به القلوب، واستقر به الإيمان في نصابه؛ ففصلت الرسالة الصفات والنعوت والأفعال أعظم من تفصيل الأمر والنهي، وقررت إثباتها أكمل تقرير في أبلغ لفظ، وأبعده عن الإجمال والاحتمال، وأمنعه من قبول التأويل. ولذلك كان تأويل آيات الصفات وأحاديثها بما يخرجها عن حقائقها من جنس تأويل آيات المعاد وأخباره، بل أبعد منه وأفسد لوجوه كثيرة ذكرناها في كتاب «الصواعق المرسلة على الجهمية والمعطلة». بل تأويل آيات الصفات بما يخرجها عن')
b=source(305,1,'حقائقها كتأويل آيات الأمر والنهي، فالباب كله باب ذات واحد، ومصدره واحد، ومقصوده واحد، وهو إثبات حقائقه والإيمان بها.')
unit([a,b],'Что касается послания, то оно подробно утвердило качества так, что устранило сомнительные доводы, сняло покров, дало достоверное знание и рассеяло сомнения и колебания. От этого прояснилось в груди, успокоились сердца, а вера утвердилась на подобающем ей месте. Послание разъяснило качества, свойства и действия подробнее, чем повеления и запреты. Оно утвердило их самым полным образом, в наиболее выразительных словах, наиболее далёких от неопределённости и многозначности и менее всего допускающих иносказательное перетолкование. Поэтому перетолкование аятов и хадисов о качествах, выводящее их за пределы подлинного смысла, подобно перетолкованию аятов и сообщений о воскресении и будущей жизни. Более того, оно ещё более далеко от истины и порочно по многим причинам, которые мы изложили в книге «Ас-Саваик аль-мурсаля аля аль-джахмийя ва-ль-муаттыля». Перетолкование аятов о качествах с отступлением от их подлинного смысла подобно также перетолкованию аятов с повелениями и запретами. Всё это составляет единый раздел: источник у него один и цель одна — утверждение подлинного смысла этих текстов и вера в него.')
pair(305,2,'ولذلك سطا على تأويل آيات المعاد قوم، وقالوا: فعلنا فيها كفعل المتكلمين في آيات الصفات، بل نحن أعذر، فإن اشتمال الكتب الإلهية على الصفات والعلو وقيام الأفعال أعظم من نصوص المعاد للأبدان بكثير، فإذا ساغ لكم تأويلها، فكيف حرم علينا نحن تأويل آيات المعاد؟ وكذلك سطا قوم آخرون على تأويل آيات الأمر والنهي، وقالوا: فعلنا فيها كفعل أولئك في آيات الصفات، مع كثرتها وتنوعها، وآيات الأحكام لا تبلغ زيادة على خمسمائة آية.','Поэтому одни люди дерзнули перетолковывать аяты о воскресении и будущей жизни, говоря: «Мы поступили с ними так же, как мутакаллимы поступают с аятами о качествах. Более того, у нас больше оправданий: в Божественных Писаниях гораздо больше говорится о качествах, возвышенности Аллаха и присущих Ему действиях, чем о телесном воскресении. Если вам позволено перетолковывать эти тексты, почему же нам запрещено перетолковывать аяты о воскресении?» Другие подобным образом дерзнули перетолковывать аяты с повелениями и запретами. Они сказали: «Мы поступили с ними так же, как те поступают с аятами о качествах, несмотря на их многочисленность и разнообразие; ведь число аятов с правовыми предписаниями не превышает пятисот».')
pair(305,3,'قالوا: وما يظن أنه معارض من العقليات لنصوص الصفات، فعندنا معارض عقلي لنصوص المعاد من جنسه أو أقوى منه. قال متأولو آيات الأحكام على خلاف حقائقها وظواهرها: الذي سوغ لنا هذا التأويل القواعد التي أصلتموها لنا وجعلتموها أصولا نرجع إليها، فلما طردناها كان مؤداها: أن الله ما تكلم بشيء قط، ولا يتكلم، ولا يأمر ولا ينهى، ولا له صفة تقوم به، ولا يفعل شيئا، وطرد هذا الأصل: لزوم تأويل آيات الأمر والنهي، والوعد والوعيد، والثواب والعقاب.','Первые сказали: «Если вы полагаете, что какие-то рациональные доводы противоречат текстам о качествах, то у нас есть рациональные возражения против текстов о воскресении — того же рода или ещё более сильные». А те, кто перетолковывает аяты с правовыми предписаниями вопреки их подлинному и явному смыслу, сказали: «Основанием для такого перетолкования послужили правила, которые вы установили для нас и сделали основами, к которым следует обращаться. Когда мы последовательно применили их, вывод оказался таким: Аллах никогда ничего не говорил и не говорит, не повелевает и не запрещает; у Него нет присущего Ему качества, и Он ничего не совершает. Последовательное применение этой основы неизбежно ведёт к перетолкованию аятов о повелениях и запретах, обещании и угрозе, награде и наказании».')
pair(306,1,'وقد ذكرنا في كتاب «الصواعق» أن تأويل آيات الصفات وأخبارها بما يخرجها عن حقائقها هو أصل فساد الدنيا والدين وزوال الممالك وتسلط أعداء الإسلام عليه إنما كان بسبب التأويل، ويعرف هذا من له اطلاع وخبرة بما جرى في العالم، ولهذا يحرم عقلاء الفلاسفة التأويل مع اعتقادهم لصحته، لأنه سبب لفساد العالم وتعطيل الشرائع.','В книге «Ас-Саваик» мы уже разъяснили, что перетолкование аятов и сообщений о качествах с отступлением от их подлинного смысла лежит в основе порчи мирской жизни и религии. Падение государств и господство врагов ислама над ним происходили именно из-за такого перетолкования. Это известно тому, кто знаком с событиями в мире и разбирается в них. Поэтому разумные среди философов запрещают перетолкование, хотя сами считают его правильным: оно ведёт к порче мира и упразднению религиозных законов.')
pair(306,2,'ومن تأمل كيفية ورود آيات الصفات في القرآن والسنة علم قطعا بطلان تأويلها بما يخرجها عن حقائقها، فإنها وردت على وجه لا يحتمل معه التأويل بوجه. فانظر إلى قوله تعالى: {هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك} [الأنعام: 158]، هل يحتمل هذا التقسيم والتنويع تأويل إتيان الرب ـ جل جلاله ـ بإتيان ملائكته أو آياته؟ وهل يبقى مع هذا السياق شبهة أصلا أنه إتيانه بنفسه؟','Тот, кто внимательно рассмотрит, как аяты о качествах приведены в Коране и Сунне, несомненно поймёт несостоятельность перетолкования, выводящего их за пределы подлинного смысла: они приведены так, что вовсе не допускают подобного перетолкования. Взгляни на слова Всевышнего: {هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك} — «Неужели они ожидают лишь того, что к ним придут ангелы, или придёт твой Господь, или придут некоторые знамения твоего Господа?» (6:158). Разве такое разделение и перечисление различных случаев позволяет истолковать пришествие Господа, велико Его величие, как пришествие Его ангелов или Его знамений? Разве при таком контексте остаётся хотя бы малейшее сомнение в том, что речь идёт о Его собственном пришествии?')
pair(306,3,'وكذلك قوله: {إنا أوحينا إليك كما أوحينا إلى نوح والنبيين من بعده} إلى أن قال: {وكلم الله موسى تكليما} [النساء: 163–164]، ففرق بين الإيحاء العام والتكليم الخاص، وجعلهما نوعين، ثم أكد فعل التكليم بالمصدر الرافع توهم ما يثيره المحرفون. وكذلك قوله: {وما كان لبشر أن يكلمه الله إلا وحيا أو من وراء حجاب أو يرسل رسولا} [الشورى: 51]، فنوع تكليمه إلى تكليم بالواسطة، وتكليم بغير واسطة. وكذلك قوله لموسى عليه السلام: {إني اصطفيتك على الناس برسالاتي وبكلامي} [الأعراف: 144]، ففرق بين الرسالة والكلام، والرسالة إنما هي بكلامه.','Таковы и Его слова: {إنا أوحينا إليك كما أوحينا إلى نوح والنبيين من بعده} — «Воистину, Мы внушили тебе откровение, как внушили его Нуху и пророкам после него», — вплоть до слов: {وكلم الله موسى تكليما} — «И Аллах говорил с Мусой непосредственно» (4:163–164). Он различил общее внушение откровения и особое обращение с речью, выделив их как два вида. Затем Он подчеркнул действие речи отглагольным существительным, устраняющим то ложное представление, которое пытаются вызвать искажающие смысл. Таковы и Его слова: {وما كان لبشر أن يكلمه الله إلا وحيا أو من وراء حجاب أو يرسل رسولا} — «Человеку не дано, чтобы Аллах говорил с ним иначе как посредством откровения, или из-за завесы, или послав посланника» (42:51). Он разделил Своё обращение с речью на обращение через посредника и без посредника. Таковы и Его слова Мусе, мир ему: {إني اصطفيتك على الناس برسالاتي وبكلامي} — «Я избрал тебя перед людьми Своими посланиями и Своей речью» (7:144). Он различил послание и речь, хотя послание передаётся именно Его речью.')
pair(307,1,'وكذلك قول النبي صلى الله عليه وسلم: «إنكم ترون ربكم عيانا، كما ترون القمر ليلة البدر في الصحو ليس دونه سحاب، وكما ترون الشمس في الظهيرة صحوا ليس دونها سحاب». ومعلوم أن هذا البيان الكاشف للمراد المحرر له يزيل إرادة التأويل قطعا، ولا يرتاب في هذا من له عقل ودين.','Таковы и слова Пророка, мир ему и благословение Аллаха: «Вы увидите своего Господа воочию, как видите луну в ночь полнолуния при ясном небе, когда её не закрывают облака, и как видите солнце в полдень при ясном небе, когда его не закрывают облака». Известно, что такое разъяснение, раскрывающее и точно определяющее подразумеваемый смысл, безусловно исключает, что здесь подразумевалось иносказание. В этом не сомневается человек, наделённый разумом и верой.')
pair(307,2,'قوله: (وظهرت شواهدها في الصنعة)، هذا هو الطريق الثاني من طرق إثبات الصفات، وهو دلالة الصنعة عليها، فإن المخلوق يدل على وجود خالقه، وعلى حياته، وعلى قدرته، وعلى علمه ومشيئته، فإن الفعل الاختياري يستلزم ذلك استلزاما ضروريا.','Его слова: «И свидетельства о них проявились в творении». Это второй путь утверждения качеств — свидетельство творения о них. Сотворённое указывает на существование своего Творца, на Его жизнь, могущество, знание и волю: действие, совершённое по выбору, с необходимостью предполагает всё это.')
pair(307,3,'وما فيه من الإتقان والإحكام ووقوعه على أكمل الوجوه يدل على حكمة فاعله وعنايته.','Точность и совершенство сотворённого, а также его осуществление наилучшим образом указывают на мудрость и попечение Того, Кто его совершил.')
pair(307,4,'وما فيه من الإحسان والنفع، ووصول المنافع العظيمة إلى المخلوق يدل على رحمة خالقه، وإحسانه وجوده.','Присущие ему благодеяние и польза, а также получение творением великих благ указывают на милость его Творца, Его благодеяние и щедрость.')
pair(307,5,'وما فيه من آثار الكمال يدل على أن خالقه أكمل منه، فمعطي الكمال أحق بالكمال، وخالق الأسماع والأبصار والنطق أحق بأن يكون سميعا بصيرا متكلما، وخالق الحياة والعلوم والقدر والإرادات أحق بأن يكون هو كذلك في نفسه. وما في المخلوقات من أنواع التخصيصات من أدل شيء على إرادة الرب تعالى ومشيئته، وحكمته التي اقتضت التخصيص.','Следы совершенства в сотворённом указывают на то, что его Творец совершеннее его. Тот, Кто дарует совершенство, Сам более достоин совершенства. Творец слуха, зрения и речи тем более достоин быть Слышащим, Видящим и Говорящим. Творец жизни, знаний, способностей и воли тем более достоин Сам обладать соответствующими качествами. Различные виды наделения творений особыми свойствами — одно из наиболее явных свидетельств стремления и воли Всевышнего Господа, а также Его мудрости, определившей такое наделение.')
a=source(307,6,'وحصول الإجابة عقيب سؤال المطلوب على الوجه المطلوب دليل')
b=source(308,1,'على علم الرب تعالى بالجزئيات، وعلى سمعه لسؤال عبيده، وعلى قدرته على قضاء حوائجهم، وعلى رأفته ورحمته بهم.')
unit([a,b],'Получение ответа вслед за просьбой о желаемом именно в том виде, о котором просят, свидетельствует о знании Всевышним Господом частностей, о том, что Он слышит просьбы Своих рабов, способен удовлетворить их нужды и проявляет к ним сострадание и милость.')
pair(308,2,'والإحسان إلى المطيعين، والتقريب لهم والإكرام، وإعلاء درجاتهم يدل على محبته ورضاه. وعقوبته للعصاة والظلمة وأعداء رسله بأنواع العقوبات المشهودة تدل على صفة الغضب والسخط، والإبعاد والطرد والإقصاء يدل على المقت والبغض.','Благодеяние к покорным, их приближение и почитание, возвышение их степеней свидетельствуют о Его любви и довольстве. А наказание ослушников, притеснителей и врагов Его посланников различными наблюдаемыми наказаниями свидетельствует о качествах гнева и негодования. Удаление, изгнание и отстранение свидетельствуют о ненависти и неприязни.')
pair(308,3,'فهذه الدلالات من جنس واحد عند التأمل. ولهذا دعا سبحانه عباده في كتابه إلى الاستدلال بذلك على صفاته، فهو يثبت العلم بربوبيته ووحدانيته، وصفات كماله بآثار صنعه المشهودة، والقرآن مملوء من ذلك.','Если вдуматься, все эти свидетельства относятся к одному роду. Поэтому Пречистый в Своей Книге призывает рабов заключать по ним о Его качествах. Он утверждает знание о Своём господстве, единственности и качествах совершенства посредством наблюдаемых следов Своего творения. Коран полон таких указаний.')
pair(308,4,'فيظهر شاهد اسم «الخالق» من نفس المخلوق، وشاهد اسم «الرزاق» من وجود الرزق، وشاهد اسم «الرحيم» من شهود الرحمة المبثوثة في العالم، واسم «المعطي» من وجود العطاء الذي هو مدرار لا ينقطع لحظة واحدة، واسم «الحليم» من حلمه عن الجناة والعصاة وعدم معاجلتهم، واسم «الغفور» و«التواب» من مغفرة الذنوب وقبول التوبة، ويظهر شاهد اسم «الحكيم» من العلم بما في خلقه وأمره من الحكم والمصالح ووجوه المنافع. وهكذا كل اسم من أسمائه الحسنى له شاهد في خلقه وأمره، يعرفه من عرفه ويجهله من جهله، فالخلق والأمر من أعظم شواهد أسمائه وصفاته.','Свидетельство об имени «Творец» проявляется в самом сотворённом; об имени «Наделяющий уделом» — в наличии удела; об имени «Милосердный» — в созерцании милости, разлитой в мире. Свидетельство об имени «Дарующий» — в наличии непрестанно изливающихся даров, которые не иссякают ни на мгновение; об имени «Кроткий» — в Его снисхождении к преступающим и ослушникам и в том, что Он не спешит их наказывать. Свидетельство об именах «Прощающий» и «Принимающий покаяние» — в прощении грехов и принятии покаяния. Свидетельство об имени «Мудрый» проявляется в знании мудрости, благих целей и различных видов пользы, заключённых в Его творении и повелении. Так у каждого из Его прекрасных имён есть свидетельство в Его творении и повелении: одни познают его, а другие остаются в неведении о нём. Творение и повеление — одни из величайших свидетельств о Его именах и качествах.')
